const items = $input.all();

let voiceOverFile;
let transcriptFile;
let backgroundMusicFile;
const backgroundImages = [];

items.forEach(item => {
  if (!item.binary) return;

  for (const key of Object.keys(item.binary)) {
    const file = item.binary[key];

    if (key === 'voice_over') {
      voiceOverFile = file;
    } 
    else if (key === 'transcription') {
      transcriptFile = file;
    } 
    else if (key === 'background_music') {
      backgroundMusicFile = file;
    } 
    else if (key === 'background_image') {
      backgroundImages.push(file);
    }
  }
});

const finalBinary = {
  voice_over: voiceOverFile,
  transcription: transcriptFile,
  background_music: backgroundMusicFile
};

// WICHTIG: Wir nutzen hier den Key "images" (wie in deinem curl -F "images=...")
// n8n erlaubt es technisch, mehrere Binary-Objekte unter dem gleichen Key 
// in die Pipeline zu legen, WENN der Empfänger-Node (HTTP Request) das unterstützt.
backgroundImages.forEach((img, index) => {
  finalBinary[`images_${index}`] = img; 
});

return [{
  json: {
    total_images: backgroundImages.length
  },
  binary: finalBinary
}];
